<script setup>
import { computed, ref } from 'vue';
import { router } from '@inertiajs/vue3';
const props = defineProps({ title:String, records:Object, fields:Array, createUrl:String, updateUrl:String, deleteUrl:String, institutions:{type:Array,default:()=>[]}, statistics:Object });
const rows=computed(()=>props.records?.data??[]); const query=ref(''); const modal=ref(false); const selected=ref(null); const form=ref({});
const visible=computed(()=>rows.value.filter(row=>!query.value||Object.values(row).join(' ').toLowerCase().includes(query.value.toLowerCase())));
function blank(){ return Object.fromEntries(props.fields.map(f=>[f.key,f.default??(f.type==='checkbox'?false:'')])) }
function open(row=null){ selected.value=row; form.value=row?Object.fromEntries(props.fields.map(f=>[f.key,row[f.key]??(f.type==='checkbox'?false:'')])):blank(); modal.value=true; }
function save(){ const url=selected.value?props.updateUrl.replace(':id',selected.value.id):props.createUrl; router[selected.value?'put':'post'](url,form.value,{preserveScroll:true,onSuccess:()=>modal.value=false}); }
function remove(row){ if(confirm('¿Eliminar este registro?')) router.delete(props.deleteUrl.replace(':id',row.id),{preserveScroll:true}); }
</script>
<template><div class="module-page"><div class="module-header"><div><h2>{{ title }}</h2><p>{{ records?.total ?? rows.length }} registros</p></div><button v-if="createUrl" class="module-primary" @click="open()">+ Nuevo</button></div><div v-if="statistics" class="module-toolbar"><b v-for="(value,key) in statistics" :key="key">{{ key }}: {{ value }}</b></div><div class="module-toolbar"><label>Buscar <input v-model="query"></label></div><div class="module-table-wrap"><table class="module-table"><thead><tr><th v-for="field in fields" :key="field.key">{{ field.label }}</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td v-for="field in fields" :key="field.key">{{ field.options?.find(o=>o.value===row[field.key])?.label ?? row[field.key] ?? '-' }}</td><td><button class="row-action" @click="open(row)">Ver / editar</button><button v-if="deleteUrl" class="row-action delete" @click="remove(row)">Eliminar</button></td></tr><tr v-if="!visible.length"><td :colspan="fields.length+1">Sin registros.</td></tr></tbody></table></div><div v-if="records?.links?.length" class="module-toolbar"><button v-for="link in records.links" :key="link.label" :disabled="!link.url" @click="link.url&&router.visit(link.url,{preserveScroll:true})" v-html="link.label"/></div></div><div v-if="modal" class="modal-overlay" @click.self="modal=false"><form class="quote-modal module-form" @submit.prevent="save"><header><h3>{{ selected ? 'Editar registro' : 'Nuevo registro' }}</h3><button type="button" class="modal-close" @click="modal=false">x</button></header><label v-for="field in fields" :key="field.key">{{ field.label }}<select v-if="field.type==='select'" v-model="form[field.key]"><option value="">Seleccionar</option><option v-for="o in field.options" :key="o.value" :value="o.value">{{ o.label }}</option></select><select v-else-if="field.type==='institution'" v-model="form[field.key]"><option value="">Seleccionar institución</option><option v-for="item in institutions" :key="item.id" :value="item.id">{{ item.name }}</option></select><textarea v-else-if="field.type==='textarea'" v-model="form[field.key]"/><input v-else-if="field.type==='checkbox'" v-model="form[field.key]" type="checkbox"><input v-else v-model="form[field.key]" :type="field.type??'text'"></label><footer><button class="module-primary">Guardar</button></footer></form></div></template>
